function twoSum(arr, target) {
  let lo = 0, hi = arr.length - 1;   // arr는 오름차순 정렬돼 있다고 가정
  while (lo < hi) {
    const sum = arr[lo] + arr[hi];
    if (sum === target) return [lo, hi];
    if (sum < target) lo++;          // 합이 작으면 왼쪽을 키운다
    else hi--;                       // 합이 크면 오른쪽을 줄인다
  }
  return null;
}

