function minLen(arr, target) {
  let lo = 0, sum = 0, best = Infinity;
  for (let hi = 0; hi < arr.length; hi++) {
    sum += arr[hi];
    while (sum >= target) {
      best = Math.min(best, hi - lo + 1);
      sum -= arr[lo++];
    }
  }
  return best;
}

