def min_len(arr, target):
    lo, total, best = 0, 0, float('inf')
    for hi in range(len(arr)):
        total += arr[hi]
        while total >= target:
            best = min(best, hi - lo + 1)
            total -= arr[lo]
            lo += 1
    return best
